// sheets-adapter (live): section 13 contract over the Google Sheets API v4.
const i = $input.first().json;
const base = 'https://sheets.googleapis.com/v4/spreadsheets/';
// message_log columns (design section 14), in sheet column order
const LOG_COLUMNS = ['logged_at', 'wa_id', 'direction', 'author', 'kind', 'text', 'route', 'stage', 'classifier', 'draft',
  'problems', 'facts_version', 'execution_id', 'workflow_version', 'input_tokens', 'output_tokens', 'reply_ms'];
switch (i.op) {
  case 'read_facts':
    return [{ json: { op: i.op, method: 'GET', url: base + $env.FACTS_SHEET_ID +
      '/values:batchGet?ranges=facts&ranges=prices&ranges=service_areas&ranges=hours&valueRenderOption=FORMATTED_VALUE' } }];
  case 'append_log': {
    const r = i.row || {};
    const cell = (v) => (v === undefined || v === null ? '' : typeof v === 'object' ? JSON.stringify(v) : v);
    return [{ json: { op: i.op, method: 'POST',
      url: base + $env.LOG_SHEET_ID + '/values/log!A1:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS',
      body: { values: [LOG_COLUMNS.map((k) => cell(r[k]))] } } }];
  }
  default:
    return [{ json: { op: i.op, invalid: true } }];
}

// Maps an HTTP status (or a network failure) to the section 13 error kinds.
function fail(kind, message) { return [{ json: { ok: false, error: { kind, message: String(message).slice(0, 300) } } }]; }
function httpFail(res, what) {
  if (!res || res.statusCode === undefined) return fail('unavailable', what + ': ' + JSON.stringify((res && res.error) || res).slice(0, 200));
  const s = res.statusCode;
  const msg = what + ' ' + s + ': ' + JSON.stringify(res.body).slice(0, 200);
  if (s === 429 || s >= 500) return fail('unavailable', msg);
  if (s === 404 || s === 410) return fail('not_found', msg);
  if (s === 409) return fail('conflict', msg);
  if (s === 401 || s === 403) return fail('unavailable', msg);
  return fail('invalid', msg);
}
const ok2xx = (res) => res && res.statusCode >= 200 && res.statusCode < 300;


const crypto = require('crypto');
const req = $('sheets:request').first().json;
if (req.invalid) return fail('invalid', 'unknown op ' + JSON.stringify(req.op) + ' for sheets');
const res = $input.first().json;
if (!ok2xx(res)) return httpFail(res, req.op);
if (req.op === 'append_log') return [{ json: { ok: true } }];
// read_facts: each tab's first row is the header; every value is returned as a string, like the CSV copy the fake reads
const tabs = ['facts', 'prices', 'service_areas', 'hours'];
const ranges = (res.body && res.body.valueRanges) || [];
const out = { ok: true };
tabs.forEach((tab, n) => {
  const values = (ranges[n] && ranges[n].values) || [];
  const header = (values[0] || []).map((h) => String(h).trim());
  out[tab] = values.slice(1)
    .filter((row) => row.some((v) => String(v).trim() !== ''))
    .map((row) => Object.fromEntries(header.map((h, k) => [h, row[k] === undefined ? '' : String(row[k])])));
});
out.version = crypto.createHash('sha256').update(JSON.stringify(tabs.map((t) => out[t]))).digest('hex').slice(0, 12);
return [{ json: out }];
